27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
29	            OwnerRepository ownerRepository) {
30	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return;
32	        }
33	        String lastName = normalize(owner.getLastName());
34	        String address = normalizeAddress(owner.getAddress());
35	        String householdId = householdId(lastName, address);
36	        owner.setHouseholdId(householdId);
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (lastName.equals(normalize(existing.getLastName()))
39	                    && address.equals(normalizeAddress(existing.getAddress()))
40	                    && existing.getHouseholdId() == null) {
41	                existing.setHouseholdId(householdId);
42	                ownerRepository.save(existing);
43	            }
44	        }
45	    }
