52	    private static String sha256hex(String value) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest(value.getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder(digest.length * 2);
57	            for (byte b : digest) {
58	                sb.append(String.format("%02x", b));
59	            }
60	            return sb.toString();
61	        }
62	        catch (NoSuchAlgorithmException e) {
63	            throw new IllegalStateException(e);
64	        }
65	    }
66	
67	    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
68	    private static String normalize(String value) {
69	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase();
70	    }
